cat > src/util.cc <<'EOF'
#include "util.h"

#include <cstdarg>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cerrno>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/types.h>

[[noreturn]] void Fatal(const char* msg, ...) {
  va_list ap;
  fprintf(stderr, "ninja: fatal: ");
  va_start(ap, msg);
  vfprintf(stderr, msg, ap);
  va_end(ap);
  fprintf(stderr, "\n");
  exit(1);
}

void Warning(const char* msg, ...) {
  va_list ap;
  fprintf(stderr, "ninja: warning: ");
  va_start(ap, msg);
  vfprintf(stderr, msg, ap);
  va_end(ap);
  fprintf(stderr, "\n");
}

void Error(const char* msg, ...) {
  va_list ap;
  fprintf(stderr, "ninja: error: ");
  va_start(ap, msg);
  vfprintf(stderr, msg, ap);
  va_end(ap);
  fprintf(stderr, "\n");
}

bool CanonicalizePath(std::string* path, uint64_t* slash_bits, std::string* err) {
  size_t len = path->size();
  char* str = 0;
  if (len > 0)
    str = &(*path)[0];
  if (!CanonicalizePath(str, &len, slash_bits, err))
    return false;
  path->resize(len);
  return true;
}

static bool IsPathSeparator(char c) {
  return c == '/';
}

bool CanonicalizePath(char* path, size_t* len, uint64_t* slash_bits, std::string* err) {
  if (*len == 0) {
    *err = "empty path";
    return false;
  }

  const int kMaxPathComponents = 60;
  char* components[kMaxPathComponents];
  int component_count = 0;

  char* start = path;
  char* dst = start;
  char* dst_start = dst;
  const char* src = start;
  const char* end = start + *len;
  const char* src_next;

  if (IsPathSeparator(*src)) {
    *dst++ = *src++;
    ++dst_start;
  }

  while (src < end) {
    if (*src == '.') {
      if (src + 1 == end || IsPathSeparator(src[1])) {
        // "." component; skip it.
        src += 2;
        continue;
      } else if (src[1] == '.' && (src + 2 == end || IsPathSeparator(src[2]))) {
        // ".." component.  Back up if possible.
        if (component_count > 0) {
          dst = components[component_count - 1];
          src += 3;
          --component_count;
        } else {
          *dst++ = *src++;
          *dst++ = *src++;
          if (src < end) *dst++ = *src++;
        }
        continue;
      }
    }

    if (IsPathSeparator(*src)) {
      ++src;
      continue;
    }

    if (component_count == kMaxPathComponents)
      Fatal("path has too many components : %s", path);
    components[component_count++] = dst;

    while (src != end && !IsPathSeparator(*src))
      *dst++ = *src++;
    if (src != end) *dst++ = *src++;  // Copy '/' or final \0 char as well.
  }

  if (dst == dst_start) {
    *dst++ = '.';
    *dst++ = '\0';
    *len = 1;
    if (slash_bits) *slash_bits = 0;
    return true;
  }

  *len = dst - start - (dst > dst_start && IsPathSeparator(dst[-1]) ? 1 : 0);
  if (slash_bits) *slash_bits = 0;
  return true;
}

int ReadFile(const std::string& path, std::string* contents, std::string* err) {
  FILE* f = fopen(path.c_str(), "rb");
  if (!f) {
    err->assign(strerror(errno));
    return -errno;
  }

  struct stat st;
  if (fstat(fileno(f), &st) < 0) {
    err->assign(strerror(errno));
    fclose(f);
    return -errno;
  }

  contents->reserve(st.st_size + 16);

  char buf[64 << 10];
  size_t len;
  while (!feof(f) && (len = fread(buf, 1, sizeof(buf), f)) > 0) {
    contents->append(buf, len);
  }
  if (ferror(f)) {
    err->assign(strerror(errno));
    contents->clear();
    fclose(f);
    return -errno;
  }
  fclose(f);
  return 0;
}

std::string StripAnsiEscapeCodes(const std::string& in) {
  std::string out;
  out.reserve(in.size());
  for (size_t i = 0; i < in.size(); ++i) {
    if (in[i] != '\x1B') {
      out.push_back(in[i]);
      continue;
    }
    ++i;
    if (i >= in.size()) break;
    if (in[i] != '[') continue;
    ++i;
    while (i < in.size() && !(in[i] >= '@' && in[i] <= '~')) ++i;
  }
  return out;
}

int64_t GetTimeMillis() {
  struct timeval tv;
  gettimeofday(&tv, nullptr);
  return (int64_t)tv.tv_sec * 1000 + tv.tv_usec / 1000;
}

int GetProcessorCount() {
  long n = sysconf(_SC_NPROCESSORS_ONLN);
  if (n <= 0) return 1;
  // Ninja bumps by 2.
  return (int)n + 2;
}

std::string GetShellEscapedString(const std::string& input) {
  // If the string contains only safe characters, return as-is.
  const char* kSafe = "%+,-./0123456789:=@ABCDEFGHIJKLMNOPQRSTUVWXYZ_abcdefghijklmnopqrstuvwxyz";
  if (input.find_first_not_of(kSafe) == std::string::npos)
    return input;

  std::string r;
  r.reserve(input.size() + 2);
  r.push_back('\'');
  for (char c : input) {
    if (c == '\'') {
      r.append("'\\''");
    } else {
      r.push_back(c);
    }
  }
  r.push_back('\'');
  return r;
}

std::vector<std::string> SplitStringPiece(const std::string& input, char sep) {
  std::vector<std::string> r;
  size_t start = 0;
  for (size_t i = 0; i < input.size(); ++i) {
    if (input[i] == sep) {
      r.push_back(input.substr(start, i - start));
      start = i + 1;
    }
  }
  r.push_back(input.substr(start));
  return r;
}

bool islatinalpha(int c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

std::string ToLower(const std::string& s) {
  std::string r;
  r.reserve(s.size());
  for (char c : s) r.push_back((char)tolower((unsigned char)c));
  return r;
}

std::string FormatHumanReadableSize(uint64_t size) {
  char buf[32];
  snprintf(buf, sizeof(buf), "%lu", (unsigned long)size);
  return buf;
}
EOF

