bool CanonicalizePath(char* path, size_t* len, uint64_t* slash_bits, std::string* err) {
  if (*len == 0) {
    *err = "empty path";
    return false;
  }

  const int kMaxPathComponents = 60;
  char* components[kMaxPathComponents];
  int component_count = 0;

  char* start = path;
  char* dst = start;
  char* dst_start = dst;
  const char* src = start;
  const char* end = start + *len;
  const char* src_next;

  if (IsPathSeparator(*src)) {
    *dst++ = *src++;
    ++dst_start;
  }

  while (src < end) {
    if (*src == '.') {
      if (src + 1 == end || IsPathSeparator(src[1])) {
        // "." component; skip it.
        src += 2;
        continue;
      } else if (src[1] == '.' && (src + 2 == end || IsPathSeparator(src[2]))) {
        // ".." component.  Back up if possible.
        if (component_count > 0) {
          dst = components[component_count - 1];
          src += 3;
          --component_count;
        } else {
          *dst++ = *src++;
          *dst++ = *src++;
          if (src < end) *dst++ = *src++;
        }
        continue;
      }
    }

    if (IsPathSeparator(*src)) {
      ++src;
      continue;
    }

    if (component_count == kMaxPathComponents)
      Fatal("path has too many components : %s", path);
    components[component_count++] = dst;

    while (src != end && !IsPathSeparator(*src))
      *dst++ = *src++;
    if (src != end) *dst++ = *src++;  // Copy '/' or final \0 char as well.
