#include "edit_distance.h"
#include <algorithm>
#include <vector>

int EditDistance(const std::string& s1, const std::string& s2,
                 bool allow_replacements, int max_edit_distance) {
  int m = (int)s1.size();
  int n = (int)s2.size();
  std::vector<int> row(n + 1);
  for (int j = 1; j <= n; ++j) row[j] = j;
  for (int y = 1; y <= m; ++y) {
    row[0] = y;
    int prev = y - 1;
    for (int x = 1; x <= n; ++x) {
      int old = row[x];
      if (allow_replacements) {
        row[x] = std::min({row[x] + 1, row[x - 1] + 1,
                           prev + (s1[y - 1] == s2[x - 1] ? 0 : 1)});
      } else {
        if (s1[y - 1] == s2[x - 1]) row[x] = prev;
        else row[x] = std::min(row[x], row[x - 1]) + 1;
      }
      prev = old;
    }
    if (max_edit_distance) {
      int best = row[0];
      for (int x = 1; x <= n; ++x) best = std::min(best, row[x]);
      if (best > max_edit_distance) return max_edit_distance + 1;
    }
  }
  return row[n];
}
