#ifndef NINJA_EVAL_H_
#define NINJA_EVAL_H_

#include <map>
#include <string>
#include <vector>

struct Env {
  virtual ~Env() {}
  virtual std::string LookupVariable(const std::string& var) = 0;
};

// An expandable, tokenized string.
struct EvalString {
  // Each token: either literal text (RAW) or a variable reference.
  enum TokenType { RAW, SPECIAL };
  std::vector<std::pair<std::string, TokenType>> parsed_;

  void AddText(const std::string& s);
  void AddSpecial(const std::string& s);
  void Clear() { parsed_.clear(); }
  bool empty() const { return parsed_.empty(); }

  std::string Evaluate(Env* env) const;
  std::string Unparse() const;
  std::string Serialize() const;
};

// A Rule: a command and its associated bindings.
struct Rule {
  explicit Rule(const std::string& name) : name_(name) {}
  const std::string& name() const { return name_; }
  void AddBinding(const std::string& key, const EvalString& val) {
    bindings_[key] = val;
  }
  const EvalString* GetBinding(const std::string& key) const {
    auto it = bindings_.find(key);
    if (it == bindings_.end()) return nullptr;
    return &it->second;
  }
  static bool IsReservedBinding(const std::string& var);
  const std::map<std::string, EvalString>& bindings() const { return bindings_; }
 private:
  std::string name_;
  std::map<std::string, EvalString> bindings_;
};

// A BindingEnv: nested variable scope, plus rules.
struct BindingEnv : public Env {
  BindingEnv() : parent_(nullptr) {}
  explicit BindingEnv(BindingEnv* parent) : parent_(parent) {}
  std::string LookupVariable(const std::string& var) override;
  std::string LookupWithFallback(const std::string& var, const EvalString* eval, Env* env);
  void AddBinding(const std::string& key, const std::string& val) { bindings_[key] = val; }
  void AddRule(const Rule* rule);
  const Rule* LookupRule(const std::string& rule_name);
  const Rule* LookupRuleCurrentScope(const std::string& rule_name);
  const std::map<std::string, const Rule*>& GetRules() const { return rules_; }

  BindingEnv* parent() { return parent_; }
  const std::map<std::string, std::string>& bindings() const { return bindings_; }
 private:
  std::map<std::string, std::string> bindings_;
  std::map<std::string, const Rule*> rules_;
  BindingEnv* parent_;
};

#endif
