#include "eval.h"

void EvalString::AddText(const std::string& s) {
  if (!parsed_.empty() && parsed_.back().second == RAW)
    parsed_.back().first.append(s);
  else
    parsed_.push_back({s, RAW});
}

void EvalString::AddSpecial(const std::string& s) {
  parsed_.push_back({s, SPECIAL});
}

std::string EvalString::Evaluate(Env* env) const {
  std::string result;
  for (const auto& p : parsed_) {
    if (p.second == RAW) result += p.first;
    else result += env->LookupVariable(p.first);
  }
  return result;
}

std::string EvalString::Unparse() const {
  std::string result;
  for (const auto& p : parsed_) {
    bool special = (p.second == SPECIAL);
    if (special) result += "${";
    result += p.first;
    if (special) result += "}";
  }
  return result;
}

std::string EvalString::Serialize() const {
  return Unparse();
}

bool Rule::IsReservedBinding(const std::string& var) {
  return var == "command" || var == "depfile" || var == "description" ||
         var == "deps" || var == "generator" || var == "pool" ||
         var == "restat" || var == "rspfile" || var == "rspfile_content" ||
         var == "msvc_deps_prefix" || var == "dyndep";
}

std::string BindingEnv::LookupVariable(const std::string& var) {
  auto it = bindings_.find(var);
  if (it != bindings_.end()) return it->second;
  if (parent_) return parent_->LookupVariable(var);
  return "";
}

std::string BindingEnv::LookupWithFallback(const std::string& var,
                                           const EvalString* eval, Env* env) {
  auto it = bindings_.find(var);
  if (it != bindings_.end()) return it->second;
  if (eval) return eval->Evaluate(env);
  if (parent_) return parent_->LookupVariable(var);
  return "";
}

void BindingEnv::AddRule(const Rule* rule) {
  rules_[rule->name()] = rule;
}

const Rule* BindingEnv::LookupRule(const std::string& rule_name) {
  auto it = rules_.find(rule_name);
  if (it != rules_.end()) return it->second;
  if (parent_) return parent_->LookupRule(rule_name);
  return nullptr;
}

const Rule* BindingEnv::LookupRuleCurrentScope(const std::string& rule_name) {
  auto it = rules_.find(rule_name);
  if (it != rules_.end()) return it->second;
  return nullptr;
}
