#include "lexer.h"
#include <cstring>
#include <cstdio>

void Lexer::Start(const std::string& filename, const std::string& input) {
  filename_ = filename;
  input_copy_ = input;
  // Make sure input is null-terminated.
  if (input_copy_.empty() || input_copy_.back() != '\0')
    input_copy_.push_back('\0');
  input_ = input_copy_.data();
  end_ = input_copy_.data() + input_copy_.size() - 1; // don't count the null
  ofs_ = 0;
  last_token_ = nullptr;
}

const char* Lexer::TokenName(Token t) {
  switch (t) {
    case ERROR:    return "lexing error";
    case BUILD:    return "'build'";
    case COLON:    return "':'";
    case DEFAULT:  return "'default'";
    case EQUALS:   return "'='";
    case IDENT:    return "identifier";
    case INCLUDE:  return "'include'";
    case INDENT:   return "indent";
    case NEWLINE:  return "newline";
    case PIPE:     return "'|'";
    case PIPE2:    return "'||'";
    case PIPEAT:   return "'|@'";
    case POOL:     return "'pool'";
    case RULE:     return "'rule'";
    case SUBNINJA: return "'subninja'";
    case TEOF:     return "eof";
  }
  return "";
}

const char* Lexer::TokenErrorHint(Token expected) {
  switch (expected) {
    case COLON: return " ($ also escapes ':')";
    default:    return "";
  }
}

static bool IsIdentStart(char c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_';
}
static bool IsIdent(char c) {
  return IsIdentStart(c) || (c >= '0' && c <= '9') || c == '-' || c == '.';
}

void Lexer::EatWhitespace() {
  const char* p = input_ + ofs_;
  while (p < end_) {
    if (*p == ' ') { ++p; continue; }
    if (*p == '$' && p + 1 < end_ && p[1] == '\n') { p += 2; continue; }
    if (*p == '$' && p + 2 < end_ && p[1] == '\r' && p[2] == '\n') { p += 3; continue; }
    break;
  }
  ofs_ = p - input_;
}

Lexer::Token Lexer::ReadToken() {
  const char* p = input_ + ofs_;
  const char* q;
  const char* start;
  Token token;
  for (;;) {
    start = p;
    if (p >= end_) { token = TEOF; break; }
    char c = *p;
    if (c == ' ' || c == '\t') { ++p; continue; }
    if (c == '#') {
      while (p < end_ && *p != '\n') ++p;
      continue;
    }
    if (c == '\n') {
      ++p;
      token = NEWLINE;
      break;
    }
    if (c == '\r') {
      ++p;
      if (p < end_ && *p == '\n') ++p;
      token = NEWLINE;
      break;
    }
    if (c == '$' && p + 1 < end_ && p[1] == '\n') {
      p += 2;
      continue;
    }
    if (c == '$' && p + 2 < end_ && p[1] == '\r' && p[2] == '\n') {
      p += 3;
      continue;
    }
    if (c == '|') {
      ++p;
      if (p < end_ && *p == '|') { ++p; token = PIPE2; break; }
      if (p < end_ && *p == '@') { ++p; token = PIPEAT; break; }
      token = PIPE;
      break;
    }
    if (c == ':') { ++p; token = COLON; break; }
    if (c == '=') { ++p; token = EQUALS; break; }
    if (IsIdentStart(c)) {
      q = p;
      while (q < end_ && IsIdent(*q)) ++q;
      size_t len = q - p;
      std::string word(p, len);
      p = q;
      if (word == "build") token = BUILD;
      else if (word == "pool") token = POOL;
      else if (word == "rule") token = RULE;
      else if (word == "default") token = DEFAULT;
      else if (word == "include") token = INCLUDE;
      else if (word == "subninja") token = SUBNINJA;
      else token = IDENT;
      break;
    }
    token = ERROR;
    ++p;
    break;
  }

  last_token_ = start;
  ofs_ = p - input_;
  // INDENT token: if at start of line and there's whitespace before this
  if (token != NEWLINE && token != TEOF) {
    // Look backwards for the start of the line
    const char* ls = start;
    while (ls > input_ && ls[-1] != '\n') --ls;
    if (ls < start) {
      // There is indentation; but we already skipped it. Indent token is emitted
      // when we find whitespace at start of line. Let's handle differently.
    }
  }
  return token;
}

void Lexer::UnreadToken() {
  if (last_token_) {
    ofs_ = last_token_ - input_;
    last_token_ = nullptr;
  }
}

bool Lexer::PeekToken(Token t) {
  Token got = ReadToken();
  if (got == t) return true;
  UnreadToken();
  return false;
}

bool Lexer::ReadIdent(std::string* out) {
  // Skip spaces.
  const char* p = input_ + ofs_;
  while (p < end_ && (*p == ' ' || *p == '\t')) ++p;
  const char* start = p;
  if (p >= end_ || !IsIdentStart(*p)) {
    last_token_ = start;
    ofs_ = p - input_;
    return false;
  }
  while (p < end_ && IsIdent(*p)) ++p;
  out->assign(start, p - start);
  last_token_ = start;
  ofs_ = p - input_;
  return true;
}

bool Lexer::ReadEvalString(EvalString* eval, bool path, std::string* err) {
  const char* p = input_ + ofs_;
  const char* q;
  const char* start;

  // Skip leading spaces for path mode; for varvalue mode, we need to skip
  // leading whitespace after '='.
  if (!path) {
    while (p < end_ && (*p == ' ' || *p == '\t')) ++p;
  } else {
    while (p < end_ && (*p == ' ' || *p == '\t')) ++p;
  }

  start = p;
  for (;;) {
    if (p >= end_) {
      // End of input.
      if (p > start)
        eval->AddText(std::string(start, p - start));
      last_token_ = start;
      ofs_ = p - input_;
      break;
    }
    char c = *p;
    if (c == '\n' || c == '\r') {
      // End of line
      if (p > start)
        eval->AddText(std::string(start, p - start));
      // consume newline
      if (c == '\r' && p + 1 < end_ && p[1] == '\n') ++p;
      ++p;
      last_token_ = start;
      ofs_ = p - input_;
      break;
    }
    if (path && (c == ' ' || c == '\t' || c == '|' || c == ':')) {
      if (p > start)
        eval->AddText(std::string(start, p - start));
      last_token_ = start;
      ofs_ = p - input_;
      break;
    }
    if (c == '$') {
      if (p > start) eval->AddText(std::string(start, p - start));
      ++p;
      if (p >= end_) {
        last_token_ = p;
        ofs_ = p - input_;
        return Error("bad $-escape (literal $ must be written as $$)", err);
      }
      char e = *p;
      if (e == '\n') {
        ++p;
        // Also skip leading whitespace on the next line.
        while (p < end_ && (*p == ' ' || *p == '\t')) ++p;
        start = p;
        continue;
      }
      if (e == '\r' && p + 1 < end_ && p[1] == '\n') {
        p += 2;
        while (p < end_ && (*p == ' ' || *p == '\t')) ++p;
        start = p;
        continue;
      }
      if (e == ' ') {
        eval->AddText(" ");
        ++p;
        start = p;
        continue;
      }
      if (e == ':') {
        eval->AddText(":");
        ++p;
        start = p;
        continue;
      }
      if (e == '$') {
        eval->AddText("$");
        ++p;
        start = p;
        continue;
      }
      if (e == '^') {
        eval->AddText("\n");
        ++p;
        start = p;
        continue;
      }
      if (e == '{') {
        ++p;
        const char* vstart = p;
        while (p < end_ && (IsIdent(*p) || *p == '.' )) ++p;
        if (p >= end_ || *p != '}') {
          last_token_ = p;
          ofs_ = p - input_;
          return Error("bad $-escape (literal $ must be written as $$)", err);
        }
        eval->AddSpecial(std::string(vstart, p - vstart));
        ++p;
        start = p;
        continue;
      }
      if (IsIdentStart(e)) {
        const char* vstart = p;
        while (p < end_ && IsIdent(*p)) ++p;
        eval->AddSpecial(std::string(vstart, p - vstart));
        start = p;
        continue;
      }
      last_token_ = p - 1;
      ofs_ = p - input_;
      return Error("bad $-escape (literal $ must be written as $$)", err);
    }
    ++p;
  }
  return true;
}

bool Lexer::Error(const std::string& msg, std::string* err) {
  // Compute line number.
  int line = 1;
  const char* line_start = input_;
  for (const char* p = input_; p < last_token_ && p < end_; ++p) {
    if (*p == '\n') { ++line; line_start = p + 1; }
  }
  int col = last_token_ ? (int)(last_token_ - line_start) : 0;

  char buf[512];
  snprintf(buf, sizeof(buf), "%s:%d: ", filename_.c_str(), line);
  *err = buf;
  *err += msg + "\n";

  // Show context.
  const char* line_end = last_token_ ? last_token_ : input_;
  while (line_end < end_ && *line_end != '\n') ++line_end;
  size_t ctx_len = line_end - line_start;
  const size_t kTruncate = 72;
  if (ctx_len > kTruncate) {
    ctx_len = kTruncate;
  }
  *err += std::string(line_start, ctx_len);
  *err += "\n";
  if (col > 0 && col < (int)kTruncate) {
    *err += std::string(col, ' ');
    *err += "^ near here";
  }
  return false;
}

std::string Lexer::DescribeLastError() {
  if (last_token_) {
    switch (last_token_[0]) {
      case '\t': return "tabs are not allowed, use spaces";
    }
  }
  return "lexing error";
}
