#include "graph.h"
#include "util.h"
#include <algorithm>
#include <cassert>

std::string EdgeEnv::LookupVariable(const std::string& var) {
  if (var == "in" || var == "in_newline") {
    int explicit_deps = edge_->inputs_.size() - edge_->implicit_deps_ -
                        edge_->order_only_deps_;
    char sep = var == "in" ? ' ' : '\n';
    std::vector<Node*> nodes(edge_->inputs_.begin(), edge_->inputs_.begin() + explicit_deps);
    return MakePathList(nodes, sep);
  }
  if (var == "out") {
    int explicit_outs = edge_->outputs_.size() - edge_->implicit_outs_;
    std::vector<Node*> nodes(edge_->outputs_.begin(), edge_->outputs_.begin() + explicit_outs);
    return MakePathList(nodes, ' ');
  }
  // Avoid infinite recursion.
  if (std::find(lookups_.begin(), lookups_.end(), var) != lookups_.end()) {
    std::string cycle;
    for (const auto& l : lookups_) cycle += l + " -> ";
