  Edge* AddEdge(const Rule* rule);

  Node* GetNode(const std::string& path, uint64_t slash_bits);
  Node* LookupNode(const std::string& path) const;
  Node* SpellcheckNode(const std::string& path);

  void AddIn(Edge* edge, const std::string& path, uint64_t slash_bits);
  bool AddOut(Edge* edge, const std::string& path, uint64_t slash_bits, std::string* err);
  bool AddValidation(Edge* edge, const std::string& path, uint64_t slash_bits);
  bool AddDefault(const std::string& path, std::string* err);

  std::vector<Node*> RootNodes(std::string* err) const;
  std::vector<Node*> DefaultNodes(std::string* err) const;

  // The pools, indexed by name.
  std::map<std::string, Pool*> pools_;
  // All edges.
  std::vector<Edge*> edges_;
  // All nodes, indexed by path.
  std::unordered_map<std::string, Node*> paths_;
  // Default nodes explicitly listed.
  std::vector<Node*> defaults_;

  BindingEnv bindings_;

  static Pool kDefaultPool;
  static Pool kConsolePool;
  static const Rule kPhonyRule;
};

