cat > src/state.cc <<'EOF'
#include "state.h"
#include "util.h"
#include "edit_distance.h"
#include <cstring>
#include <algorithm>

Pool State::kDefaultPool("", 0);
Pool State::kConsolePool("console", 1);
const Rule State::kPhonyRule("phony");

State::State() {
  bindings_.AddRule(&kPhonyRule);
  AddPool(&kDefaultPool);
  AddPool(&kConsolePool);
}

Pool* State::LookupPool(const std::string& pool_name) {
  auto it = pools_.find(pool_name);
  if (it == pools_.end()) return nullptr;
  return it->second;
}

void State::AddPool(Pool* pool) {
  pools_[pool->name()] = pool;
}

Edge* State::AddEdge(const Rule* rule) {
  Edge* edge = new Edge;
  edge->rule_ = rule;
  edge->pool_ = &State::kDefaultPool;
  edge->env_ = &bindings_;
  edge->id_ = (int)edges_.size();
  edges_.push_back(edge);
  return edge;
}

Node* State::GetNode(const std::string& path, uint64_t slash_bits) {
  auto it = paths_.find(path);
  if (it != paths_.end()) return it->second;
  Node* n = new Node(path, slash_bits);
  paths_[path] = n;
  return n;
}

Node* State::LookupNode(const std::string& path) const {
  auto it = paths_.find(path);
  if (it != paths_.end()) return it->second;
  return nullptr;
}

void State::AddIn(Edge* edge, const std::string& path, uint64_t slash_bits) {
  Node* node = GetNode(path, slash_bits);
  edge->inputs_.push_back(node);
  node->out_edges().push_back(edge);
}

bool State::AddOut(Edge* edge, const std::string& path, uint64_t slash_bits,
                   std::string* err) {
  Node* node = GetNode(path, slash_bits);
  if (Edge* existing = node->in_edge()) {
    if (err) *err = "multiple rules generate " + path;
    return false;
  }
  edge->outputs_.push_back(node);
  node->set_in_edge(edge);
  return true;
}

bool State::AddValidation(Edge* edge, const std::string& path, uint64_t slash_bits) {
  Node* node = GetNode(path, slash_bits);
  edge->validations_.push_back(node);
  node->validation_out_edges().push_back(edge);
  return true;
}

bool State::AddDefault(const std::string& path, std::string* err) {
  Node* node = LookupNode(path);
  if (!node) { *err = "unknown target '" + path + "'"; return false; }
  defaults_.push_back(node);
  return true;
}

std::vector<Node*> State::RootNodes(std::string* err) const {
  std::vector<Node*> root_nodes;
  for (auto* edge : edges_) {
    for (auto* out : edge->outputs_) {
      if (out->out_edges().empty()) {
        root_nodes.push_back(out);
      }
    }
  }
  return root_nodes;
}

std::vector<Node*> State::DefaultNodes(std::string* err) const {
  return defaults_.empty() ? RootNodes(err) : defaults_;
}

Node* State::SpellcheckNode(const std::string& path) {
  const bool kAllowReplacements = true;
  const int kMaxValidEditDistance = 3;
  int min_distance = kMaxValidEditDistance + 1;
  Node* result = nullptr;
  for (auto& kv : paths_) {
    int distance = EditDistance(kv.first, path, kAllowReplacements, kMaxValidEditDistance);
    if (distance < min_distance && kv.second) {
      min_distance = distance;
      result = kv.second;
    }
  }
  return result;
}
