#include "disk.h"
#include <cstring>
#include <cerrno>
#include <cstdio>
#include <sys/stat.h>
#include <unistd.h>

int64_t Stat(const std::string& path, std::string* err) {
  struct stat st;
  if (stat(path.c_str(), &st) < 0) {
    if (errno == ENOENT || errno == ENOTDIR) return 0;
    *err = std::string("stat: ") + strerror(errno);
    return -1;
  }
  return (int64_t)st.st_mtime * 1000000000LL;
}

bool MakeDir(const std::string& path) {
  return mkdir(path.c_str(), 0777) >= 0 || errno == EEXIST;
}

bool MakeDirs(const std::string& path) {
  size_t slash = path.find_last_of('/');
  if (slash == std::string::npos) return true;
  std::string dir = path.substr(0, slash);
  if (dir.empty()) return true;
  struct stat st;
  if (stat(dir.c_str(), &st) == 0) return true;
  if (!MakeDirs(dir)) return false;
  return MakeDir(dir);
}

int RemoveFile(const std::string& path) {
  return unlink(path.c_str());
}

int WriteFile(const std::string& path, const std::string& contents) {
  FILE* f = fopen(path.c_str(), "wb");
  if (!f) return -1;
  if (fwrite(contents.data(), 1, contents.size(), f) != contents.size()) {
    fclose(f);
    return -1;
  }
  fclose(f);
  return 0;
}
