ManifestParser::ManifestParser(State* state, BindingEnv* env, ManifestParserOptions options)
    : state_(state), env_(env), options_(options), quiet_(0) {}

bool ManifestParser::Load(const std::string& filename, std::string* err) {
  std::string contents;
  std::string read_err;
  if (ReadFile(filename, &contents, &read_err) < 0) {
    *err = "loading '" + filename + "': " + read_err;
    return false;
  }
  return Parse(filename, contents, err);
}

bool ManifestParser::ParseTest(const std::string& input, std::string* err) {
  quiet_ = 1;
  return Parse("input", input, err);
}

bool ManifestParser::ExpectToken(Lexer::Token expected, std::string* err) {
  Lexer::Token token = lexer_.ReadToken();
  if (token != expected) {
    std::string msg = std::string("expected ") + Lexer::TokenName(expected) +
                      ", got " + Lexer::TokenName(token) +
                      Lexer::TokenErrorHint(expected);
    return lexer_.Error(msg, err);
  }
  return true;
}

bool ManifestParser::Parse(const std::string& filename, const std::string& input,
                           std::string* err) {
  lexer_.Start(filename, input);
  for (;;) {
    Lexer::Token token = lexer_.ReadToken();
    switch (token) {
      case Lexer::POOL:
        if (!ParsePool(err)) return false;
        break;
      case Lexer::BUILD:
        if (!ParseEdge(err)) return false;
        break;
      case Lexer::RULE:
        if (!ParseRule(err)) return false;
        break;
      case Lexer::DEFAULT:
        if (!ParseDefault(err)) return false;
        break;
      case Lexer::IDENT: {
        lexer_.UnreadToken();
        std::string key;
        EvalString val;
        if (!ParseLet(&key, &val, err)) return false;
        std::string value = val.Evaluate(env_);
        env_->AddBinding(key, value);
        break;
      }
      case Lexer::INCLUDE:
        if (!ParseFileInclude(false, err)) return false;
        break;
      case Lexer::SUBNINJA:
        if (!ParseFileInclude(true, err)) return false;
        break;
      case Lexer::ERROR:
        return lexer_.Error(lexer_.DescribeLastError(), err);
      case Lexer::TEOF:
        return true;
      case Lexer::NEWLINE:
        break;
      default:
        return lexer_.Error(std::string("unexpected ") + Lexer::TokenName(token), err);
    }
  }
}

bool ManifestParser::ParseLet(std::string* key, EvalString* val, std::string* err) {
  if (!lexer_.ReadIdent(key))
    return lexer_.Error("expected variable name", err);
  if (!ExpectToken(Lexer::EQUALS, err)) return false;
  if (!lexer_.ReadVarValue(val, err)) return false;
  return true;
}

bool ManifestParser::ParsePool(std::string* err) {
  std::string name;
  if (!lexer_.ReadIdent(&name))
    return lexer_.Error("expected pool name", err);
  if (!ExpectToken(Lexer::NEWLINE, err)) return false;
  if (state_->LookupPool(name) != nullptr)
    return lexer_.Error("duplicate pool '" + name + "'", err);

  int depth = -1;
  while (lexer_.PeekToken(Lexer::INDENT) || true) {
    // Check for indented line: peek next token; if it's IDENT and starts at column > 0, treat as binding.
    // Simpler: try ParseLet if next token is IDENT
    Lexer::Token t = lexer_.ReadToken();
    if (t != Lexer::IDENT) { lexer_.UnreadToken(); break; }
    lexer_.UnreadToken();
    std::string key;
    EvalString val;
    if (!ParseLet(&key, &val, err)) return false;
    if (key == "depth") {
      std::string s = val.Evaluate(env_);
      depth = atoi(s.c_str());
      if (depth < 0) return lexer_.Error("invalid pool depth", err);
    } else {
      return lexer_.Error("unexpected variable '" + key + "'", err);
    }
  }
  if (depth < 0) return lexer_.Error("expected 'depth =' line", err);
  state_->AddPool(new Pool(name, depth));
  return true;
}

bool ManifestParser::ParseRule(std::string* err) {
  std::string name;
  if (!lexer_.ReadIdent(&name))
    return lexer_.Error("expected rule name", err);
  if (!ExpectToken(Lexer::NEWLINE, err)) return false;

  if (env_->LookupRuleCurrentScope(name) != nullptr)
    return lexer_.Error("duplicate rule '" + name + "'", err);

  Rule* rule = new Rule(name);

  while (true) {
    Lexer::Token t = lexer_.ReadToken();
    if (t != Lexer::IDENT) { lexer_.UnreadToken(); break; }
    lexer_.UnreadToken();
    std::string key;
    EvalString val;
    if (!ParseLet(&key, &val, err)) return false;
    if (Rule::IsReservedBinding(key)) {
      rule->AddBinding(key, val);
    } else {
      return lexer_.Error("unexpected variable '" + key + "'", err);
    }
  }

  if (rule->GetBinding("rspfile") == nullptr &&
      rule->GetBinding("rspfile_content") == nullptr) {
    // Not both or neither
  } else if (!rule->GetBinding("rspfile") || !rule->GetBinding("rspfile_content")) {
    return lexer_.Error("rspfile and rspfile_content need to be both specified", err);
  }

  if (!rule->GetBinding("command"))
    return lexer_.Error("expected 'command =' line", err);

  env_->AddRule(rule);
  return true;
}

bool ManifestParser::ParseEdge(std::string* err) {
  std::vector<EvalString> outs;
  std::vector<EvalString> ins;
  std::vector<EvalString> validations;
  int implicit_outs = 0;
  int implicit = 0, order_only = 0;

  {
    EvalString out;
    if (!lexer_.ReadPath(&out, err)) return false;
    while (!out.empty()) {
      outs.push_back(out);
      out.Clear();
      if (!lexer_.ReadPath(&out, err)) return false;
    }
  }

  // Implicit outs.
  if (lexer_.PeekToken(Lexer::PIPE)) {
    for (;;) {
      EvalString out;
      if (!lexer_.ReadPath(&out, err)) return err;
      if (out.empty()) break;
      outs.push_back(out);
      ++implicit_outs;
    }
  }

  if (outs.empty()) return lexer_.Error("expected path", err);

  if (!ExpectToken(Lexer::COLON, err)) return false;

  std::string rule_name;
  if (!lexer_.ReadIdent(&rule_name))
    return lexer_.Error("expected build command name", err);

  const Rule* rule = env_->LookupRule(rule_name);
  if (!rule) return lexer_.Error("unknown build rule '" + rule_name + "'", err);

  for (;;) {
    EvalString in;
    if (!lexer_.ReadPath(&in, err)) return false;
    if (in.empty()) break;
    ins.push_back(in);
  }

  // Implicit deps.
  if (lexer_.PeekToken(Lexer::PIPE)) {
    for (;;) {
      EvalString in;
      if (!lexer_.ReadPath(&in, err)) return false;
      if (in.empty()) break;
      ins.push_back(in);
      ++implicit;
    }
  }

  // Order-only.
  if (lexer_.PeekToken(Lexer::PIPE2)) {
    for (;;) {
      EvalString in;
      if (!lexer_.ReadPath(&in, err)) return false;
      if (in.empty()) break;
      ins.push_back(in);
      ++order_only;
    }
  }

  // Validations.
  if (lexer_.PeekToken(Lexer::PIPEAT)) {
    for (;;) {
      EvalString val;
      if (!lexer_.ReadPath(&val, err)) return false;
      if (val.empty()) break;
      validations.push_back(val);
    }
  }

  if (!ExpectToken(Lexer::NEWLINE, err)) return false;

  // Parse bindings
  BindingEnv* env = new BindingEnv(env_);
  while (true) {
    Lexer::Token t = lexer_.ReadToken();
    if (t != Lexer::IDENT) { lexer_.UnreadToken(); break; }
    lexer_.UnreadToken();
    std::string key;
    EvalString val;
    if (!ParseLet(&key, &val, err)) return false;
    env->AddBinding(key, val.Evaluate(env_));
  }

  Edge* edge = state_->AddEdge(rule);
  edge->env_ = env;

  // Determine pool.
  std::string pool_name = edge->GetBinding("pool");
  if (!pool_name.empty()) {
    Pool* pool = state_->LookupPool(pool_name);
    if (pool == nullptr)
      return lexer_.Error("unknown pool name '" + pool_name + "'", err);
    edge->pool_ = pool;
  }

  edge->outputs_.reserve(outs.size());
  for (size_t i = 0; i < outs.size(); ++i) {
    std::string path = outs[i].Evaluate(env);
    if (path.empty()) return lexer_.Error("empty path", err);
    uint64_t slash_bits;
    if (!CanonicalizePath(&path, &slash_bits, err)) return lexer_.Error(*err, err);
    if (!state_->AddOut(edge, path, slash_bits, err))
      return lexer_.Error(*err, err);
  }
  edge->implicit_outs_ = implicit_outs;

  edge->inputs_.reserve(ins.size());
  for (size_t i = 0; i < ins.size(); ++i) {
    std::string path = ins[i].Evaluate(env);
    if (path.empty()) return lexer_.Error("empty path", err);
    uint64_t slash_bits;
    if (!CanonicalizePath(&path, &slash_bits, err)) return lexer_.Error(*err, err);
    state_->AddIn(edge, path, slash_bits);
  }
  edge->implicit_deps_ = implicit;
  edge->order_only_deps_ = order_only;

  for (auto& v : validations) {
    std::string path = v.Evaluate(env);
    if (path.empty()) return lexer_.Error("empty path", err);
    uint64_t slash_bits;
    if (!CanonicalizePath(&path, &slash_bits, err)) return lexer_.Error(*err, err);
    state_->AddValidation(edge, path, slash_bits);
  }
  return true;
}

