#include "build.h"
#include "status.h"
#include "util.h"
#include <cstdio>
#include <set>

bool Builder::AddTarget(Node* node, std::string* err) {
  targets_.push_back(node);
  return true;
}

// Recursively collect edges needed for given targets, in topological order.
static void CollectEdges(Node* node, std::set<Edge*>& seen, std::vector<Edge*>& out) {
  Edge* edge = node->in_edge();
  if (!edge) return;
  if (seen.count(edge)) return;
  seen.insert(edge);
  for (Node* in : edge->inputs_) CollectEdges(in, seen, out);
  out.push_back(edge);
}

bool Builder::Build(std::string* err) {
  std::set<Edge*> seen;
  std::vector<Edge*> ordered;
  for (Node* t : targets_) CollectEdges(t, seen, ordered);

  // Skip phony rules.
  std::vector<Edge*> runnable;
  for (Edge* e : ordered) {
    if (e->rule_->name() == "phony") continue;
    runnable.push_back(e);
  }

  int total = (int)runnable.size();
  if (total == 0) {
    printf("ninja: no work to do.\n");
    return true;
  }

  int n = 0;
  for (Edge* e : runnable) {
    ++n;
    std::string desc;
    if (config_.verbosity == BuildConfig::VERBOSE) {
      desc = e->EvaluateCommand();
    } else {
      desc = e->GetBinding("description");
      if (desc.empty()) desc = e->EvaluateCommand();
    }
    printf("[%d/%d] %s\n", n, total, desc.c_str());
    fflush(stdout);
    if (!config_.dry_run) {
      std::string cmd = e->EvaluateCommand();
      int rc = system(cmd.c_str());
      if (rc != 0) {
        *err = "subcommand failed";
        return false;
      }
    }
  }
  return true;
}
