    printf("%s:\n", node->path().c_str());
    Edge* e = node->in_edge();
    if (e) {
      printf("  input: %s\n", e->rule_->name().c_str());
      for (size_t j = 0; j < e->inputs_.size(); ++j) {
        const char* label = "";
        if ((int)j >= (int)(e->inputs_.size() - e->implicit_deps_ - e->order_only_deps_)) {
          if ((int)j >= (int)(e->inputs_.size() - e->order_only_deps_)) label = "| ";
          else label = "| ";
        }
        printf("    %s%s\n", label, e->inputs_[j]->path().c_str());
