int RunToolGraph(State* state, int argc, char** argv) {
  std::vector<Node*> targets;
  std::string err;
  if (!CollectTargets(state, argc, argv, &targets, &err)) {
    fprintf(stderr, "ninja: error: %s\n", err.c_str());
    return 1;
  }
  printf("digraph ninja {\n");
  printf("rankdir=\"LR\"\n");
  printf("node [fontsize=10, shape=box, height=0.25]\n");
  printf("edge [fontsize=10]\n");
  std::set<Node*> vis_nodes;
  std::set<Edge*> vis_edges;
  auto node_id = [](Node* n) {
    char buf[32];
    snprintf(buf, sizeof(buf), "\"%p\"", (void*)n);
    return std::string(buf);
  };
  auto edge_id = [](Edge* e) {
    char buf[32];
    snprintf(buf, sizeof(buf), "\"%p\"", (void*)e);
    return std::string(buf);
  };

  std::function<void(Node*)> visit = [&](Node* n) {
    if (!vis_nodes.insert(n).second) return;
    Edge* e = n->in_edge();
    if (!e) {
      printf("%s [label=\"%s\"]\n", node_id(n).c_str(), n->path().c_str());
      return;
    }
    if (vis_edges.count(e)) {
      printf("%s [label=\"%s\"]\n", node_id(n).c_str(), n->path().c_str());
      return;
    }
    vis_edges.insert(e);
    if (e->inputs_.size() == 1 && e->outputs_.size() == 1) {
      // Simple edge.
      printf("%s [label=\"%s\"]\n", node_id(n).c_str(), n->path().c_str());
      printf("%s -> %s [label=\" %s\"]\n", node_id(e->inputs_[0]).c_str(),
             node_id(n).c_str(), e->rule_->name().c_str());
      visit(e->inputs_[0]);
    } else {
      // Print output node first, then edge (ellipse), then inputs.
      printf("%s [label=\"%s\"]\n", node_id(n).c_str(), n->path().c_str());
      printf("%s [label=\"%s\", shape=ellipse]\n", edge_id(e).c_str(), e->rule_->name().c_str());
      printf("%s -> %s\n", edge_id(e).c_str(), node_id(n).c_str());
      for (auto* o : e->outputs_) {
        if (o != n) printf("%s -> %s\n", edge_id(e).c_str(), node_id(o).c_str());
      }
      for (auto* in : e->inputs_) {
        printf("%s -> %s [arrowhead=none]\n", node_id(in).c_str(), edge_id(e).c_str());
      }
      for (auto* in : e->inputs_) visit(in);
    }
  };
  for (auto* t : targets) visit(t);
  printf("}\n");
  return 0;
}

// --- compdb ---
static std::string EscapeJson(const std::string& s) {
  std::string r;
  for (char c : s) {
    switch (c) {
      case '"': r += "\\\""; break;
      case '\\': r += "\\\\"; break;
      case '\b': r += "\\b"; break;
      case '\f': r += "\\f"; break;
      case '\n': r += "\\n"; break;
      case '\r': r += "\\r"; break;
      case '\t': r += "\\t"; break;
      default:
        if ((unsigned char)c < 0x20) {
          char buf[8]; snprintf(buf, sizeof(buf), "\\u%04x", c);
          r += buf;
        } else r += c;
    }
  }
  return r;
}

static std::string ExpandRspFileInCommand(const std::string& cmd, const std::string& rsp, const std::string& rsp_content) {
  if (rsp.empty()) return cmd;
  std::string needle = "@" + rsp;
  size_t pos = cmd.find(needle);
  if (pos == std::string::npos) return cmd;
  return cmd.substr(0, pos) + rsp_content + cmd.substr(pos + needle.size());
}

static void PrintCompdbEntry(const std::string& dir, Edge* e, bool expand_rsp, bool* first) {
  std::string cmd = e->EvaluateCommand();
  if (expand_rsp) {
    std::string rsp = e->GetUnescapedRspfile();
    std::string rsp_content = e->GetBinding("rspfile_content");
    cmd = ExpandRspFileInCommand(cmd, rsp, rsp_content);
  }
  for (auto* in : e->inputs_) {
    if ((size_t)(in - *e->inputs_.data()) >= e->inputs_.size() - e->implicit_deps_ - e->order_only_deps_) {
      break;
    }
    if (!*first) printf(",\n"); else *first = false;
    int explicit_n = e->inputs_.size() - e->implicit_deps_ - e->order_only_deps_;
    (void)explicit_n;
    printf("  {\n");
    printf("    \"directory\": \"%s\",\n", EscapeJson(dir).c_str());
    printf("    \"command\": \"%s\",\n", EscapeJson(cmd).c_str());
    printf("    \"file\": \"%s\",\n", EscapeJson(in->path()).c_str());
    printf("    \"output\": \"%s\"\n", e->outputs_.empty() ? "" : EscapeJson(e->outputs_[0]->path()).c_str());
    printf("  }");
  }
}

static void PrintCompdbForEdges(const std::string& dir, const std::vector<Edge*>& edges, bool expand_rsp) {
  printf("[\n");
  bool first = true;
  for (auto* e : edges) {
    if (e->rule_->name() == "phony") continue;
    int explicit_n = e->inputs_.size() - e->implicit_deps_ - e->order_only_deps_;
    std::string cmd = e->EvaluateCommand();
    if (expand_rsp) {
      std::string rsp = e->GetUnescapedRspfile();
      std::string rsp_content = e->GetBinding("rspfile_content");
      cmd = ExpandRspFileInCommand(cmd, rsp, rsp_content);
    }
    for (int i = 0; i < explicit_n; ++i) {
      if (!first) printf(",\n");
      first = false;
      printf("  {\n");
      printf("    \"directory\": \"%s\",\n", EscapeJson(dir).c_str());
      printf("    \"command\": \"%s\",\n", EscapeJson(cmd).c_str());
      printf("    \"file\": \"%s\",\n", EscapeJson(e->inputs_[i]->path()).c_str());
      printf("    \"output\": \"%s\"\n", e->outputs_.empty() ? "" : EscapeJson(e->outputs_[0]->path()).c_str());
      printf("  }");
    }
  }
  if (!first) printf("\n");
  printf("]\n");
}

int RunToolCompdb(State* state, int argc, char** argv) {
  optind = 1;
  bool expand = false;
  int c;
  while ((c = getopt(argc, argv, "hx")) != -1) {
    switch (c) {
      case 'x': expand = true; break;
      case 'h':
      default:
        printf("usage: ninja -t compdb [options] [rules]\n\noptions:\n  -x     expand @rspfile style response file invocations\n");
        return c == 'h' ? 0 : 1;
    }
  }
  char cwd[4096];
  if (!getcwd(cwd, sizeof(cwd))) strcpy(cwd, "");
  std::string dir = cwd;
  std::set<std::string> filter;
  for (int i = optind; i < argc; ++i) filter.insert(argv[i]);
  std::vector<Edge*> edges;
  for (auto* e : state->edges_) {
    if (filter.empty() || filter.count(e->rule_->name()))
      edges.push_back(e);
  }
  PrintCompdbForEdges(dir, edges, expand);
  return 0;
}

