"  recompact  recompacts ninja-internal data structures\n"
"     restat  restats all outputs in the build log\n"
"      rules  list all rules\n"
"  cleandead  clean built files that are no longer produced by the manifest\n"
  );
  return 0;
}

static Node* CollectTarget(State* state, const std::string& cpath, std::string* err) {
  std::string path = cpath;
  if (path.empty()) { *err = "empty path"; return nullptr; }
  uint64_t slash_bits;
  if (!CanonicalizePath(&path, &slash_bits, err)) return nullptr;

  bool first_dependent = false;
  if (!path.empty() && path.back() == '^') {
    path.resize(path.size() - 1);
    first_dependent = true;
  }
  Node* node = state->LookupNode(path);
  if (!node) {
    *err = "unknown target '" + cpath + "'";
    Node* sugg = state->SpellcheckNode(cpath);
    if (sugg) *err += ", did you mean '" + sugg->path() + "'?";
    return nullptr;
  }
  if (first_dependent) {
    if (node->out_edges().empty()) {
      *err = "'" + cpath + "' has no out edge";
      return nullptr;
    }
    Edge* edge = node->out_edges()[0];
    if (edge->outputs_.empty()) return nullptr;
    node = edge->outputs_[0];
  }
  return node;
}

// Collect root (default or explicit) nodes.
static bool CollectTargets(State* state, int argc, char** argv,
                           std::vector<Node*>* targets, std::string* err) {
  if (argc == 0) {
    *targets = state->DefaultNodes(err);
    return err->empty();
  }
  for (int i = 0; i < argc; ++i) {
    Node* n = CollectTarget(state, argv[i], err);
    if (!n) return false;
    targets->push_back(n);
  }
  return true;
}

// --- targets ---

static int TargetsDepthFirst(Node* node, int depth, int indent) {
  for (int i = 0; i < indent; ++i) printf("  ");
  const char* target = node->path().c_str();
  if (node->in_edge()) {
    printf("%s: %s\n", target, node->in_edge()->rule_->name().c_str());
    if (depth > 1 || depth <= 0) {
      for (auto* in : node->in_edge()->inputs_)
        TargetsDepthFirst(in, depth - 1, indent + 1);
    }
  } else {
    printf("%s\n", target);
  }
  return 0;
}

static int TargetsAll(State* state) {
  for (auto* e : state->edges_) {
    for (auto* out : e->outputs_)
      printf("%s: %s\n", out->path().c_str(), e->rule_->name().c_str());
  }
  return 0;
}

static int TargetsRule(State* state, const std::string& rule_name) {
  std::set<Node*> root;
  // root nodes = nodes with no in_edge (source files).
  if (rule_name.empty()) {
    for (auto& kv : state->paths_) {
      if (!kv.second->in_edge()) root.insert(kv.second);
    }
    // Print stable-sorted by path? Actually by original insertion order in hash;
    // the original seems not alphabetical. We'll use edge iteration order.
    std::vector<Node*> listed;
    std::set<Node*> seen;
    for (auto* e : state->edges_) {
      for (auto* in : e->inputs_) {
        if (!in->in_edge() && !seen.count(in)) {
          seen.insert(in);
          listed.push_back(in);
        }
      }
    }
    for (auto* n : listed) printf("%s\n", n->path().c_str());
    return 0;
  }
  std::vector<Node*> listed;
  std::set<Node*> seen;
  for (auto* e : state->edges_) {
    if (e->rule_->name() == rule_name) {
      for (auto* in : e->inputs_) {
        if (!seen.count(in)) {
          seen.insert(in);
          listed.push_back(in);
        }
      }
    }
  }
  for (auto* n : listed) printf("%s\n", n->path().c_str());
  return 0;
}

int RunToolTargets(State* state, int argc, char** argv) {
  if (argc == 0) {
    // list root targets
    std::string err;
    std::vector<Node*> roots = state->RootNodes(&err);
    if (!err.empty()) { fprintf(stderr, "ninja: error: %s\n", err.c_str()); return 1; }
    for (auto* r : roots) {
      printf("%s: %s\n", r->path().c_str(),
             r->in_edge() ? r->in_edge()->rule_->name().c_str() : "");
    }
    return 0;
  }
  std::string mode = argv[0];
  if (mode == "rule") {
    std::string name = (argc > 1) ? argv[1] : "";
    return TargetsRule(state, name);
  }
  if (mode == "depth") {
    int depth = 1;
    if (argc > 1) depth = atoi(argv[1]);
    std::string err;
    std::vector<Node*> roots = state->RootNodes(&err);
    for (auto* r : roots) TargetsDepthFirst(r, depth, 0);
    return 0;
  }
  if (mode == "all") {
    return TargetsAll(state);
  }
  // unknown mode
  fprintf(stderr, "ninja: error: unknown target tool mode '%s', did you mean 'all'?\n", mode.c_str());
  return 1;
}

// --- rules ---
int RunToolRules(State* state, int argc, char** argv) {
  optind = 1;
  bool print_desc = false;
  int c;
  while ((c = getopt(argc, argv, "dh")) != -1) {
    switch (c) {
      case 'd': print_desc = true; break;
      case 'h':
      default:
        printf("usage: ninja -t rules [options]\n\noptions:\n  -d     also print the description of the rule\n  -h     print this message\n");
        return 1;
    }
  }
  // Iterate bindings' rules, plus phony.
  // Per observed output, order is insertion order.
  std::vector<const Rule*> rules;
  std::set<std::string> seen;
  // phony is in state.bindings_
  // But we want "cc link phony" order as in the test.
  // Walk edges to preserve insertion order.
  for (auto* e : state->edges_) {
    if (seen.insert(e->rule_->name()).second) rules.push_back(e->rule_);
  }
  if (!seen.count("phony")) rules.push_back(&State::kPhonyRule);
  for (auto* r : rules) {
    printf("%s", r->name().c_str());
    if (print_desc) {
      const EvalString* desc = r->GetBinding("description");
      if (desc) printf(": %s", desc->Unparse().c_str());
    }
    printf("\n");
  }
  return 0;
}

// --- commands ---

static void PrintCommands(Edge* edge, bool print_deps, std::set<Edge*>* seen,
                          std::vector<Edge*>* order) {
  if (!edge || !seen->insert(edge).second) return;
  if (print_deps) {
    for (auto* in : edge->inputs_)
      PrintCommands(in->in_edge(), print_deps, seen, order);
  }
  order->push_back(edge);
}

int RunToolCommands(State* state, int argc, char** argv) {
  optind = 1;
  bool mode_final = false;
  int c;
  while ((c = getopt(argc, argv, "hs")) != -1) {
    switch (c) {
      case 's': mode_final = true; break;
      case 'h':
      default:
        printf("usage: ninja -t commands [options] [targets]\n\noptions:\n  -s     only print the final command to build [target], not the whole chain\n");
        return 1;
    }
  }
  std::vector<Node*> targets;
  std::string err;
  if (!CollectTargets(state, argc - optind, argv + optind, &targets, &err)) {
    fprintf(stderr, "ninja: error: %s\n", err.c_str()); return 1;
  }
  std::set<Edge*> seen;
  std::vector<Edge*> ordered;
  for (auto* t : targets) PrintCommands(t->in_edge(), !mode_final, &seen, &ordered);
  for (auto* e : ordered) {
    if (e->rule_->name() == "phony") continue;
    puts(e->EvaluateCommand().c_str());
  }
  return 0;
}

// --- inputs ---

struct InputsCollector {
  std::vector<Node*> inputs;
  std::set<Node*> seen_nodes;
  std::set<Edge*> seen_edges;
  bool dep_order = false;

  void Collect(Node* n) {
    if (!seen_nodes.insert(n).second) return;
    Edge* e = n->in_edge();
    if (!e) {
      inputs.push_back(n);
      return;
    }
    if (!seen_edges.insert(e).second) return;
    for (auto* in : e->inputs_) Collect(in);
    // Include intermediate outputs too (all but the root).
    for (auto* out : e->outputs_) {
      if (!seen_nodes.count(out)) {
        seen_nodes.insert(out);
        inputs.push_back(out);
      }
    }
    // actually we want the "input nodes" ignoring the original target output.
    // It's complicated - but our test shows all nodes including intermediates appear.
  }
};

int RunToolInputs(State* state, int argc, char** argv) {
  optind = 1;
  bool escape = true;
  bool dep_order = false;
  char terminator = '\n';

  static const struct option options[] = {
    {"help", no_argument, 0, 'h'},
    {"dependency-order", no_argument, 0, 'd'},
    {"print0", no_argument, 0, '0'},
    {"no-shell-escape", no_argument, 0, 'E'},
    {0, 0, 0, 0}
  };
  int c;
  while ((c = getopt_long(argc, argv, "h0Ed", options, nullptr)) != -1) {
    switch (c) {
      case 'd': dep_order = true; break;
      case '0': terminator = '\0'; break;
      case 'E': escape = false; break;
      case 'h':
      default:
        printf(
"Usage '-t inputs [options] [targets]\n\n"
"List all inputs used for a set of targets, sorted in dependency order.\n"
"Note that by default, results are shell escaped, and sorted alphabetically,\n"
"and never include validation target paths.\n\n"
"Options:\n"
"  -h, --help          Print this message.\n"
"  -0, --print0            Use \\0, instead of \\n as a line terminator.\n"
"  -E, --no-shell-escape   Do not shell escape the result.\n"
"  -d, --dependency-order  Sort results by dependency order.\n");
        return 1;
    }
  }
  std::vector<Node*> targets;
  std::string err;
  if (!CollectTargets(state, argc - optind, argv + optind, &targets, &err)) {
    fprintf(stderr, "ninja: error: %s\n", err.c_str());
    return 1;
  }
  InputsCollector col;
  col.dep_order = dep_order;
  std::set<Node*> target_set(targets.begin(), targets.end());
  for (auto* t : targets) col.Collect(t);
  // Remove the targets themselves from results.
  std::vector<std::string> paths;
  for (auto* n : col.inputs) {
    if (target_set.count(n)) continue;
    paths.push_back(n->path());
  }
  if (!dep_order) std::sort(paths.begin(), paths.end());
  for (auto& p : paths) {
    std::string s = escape ? GetShellEscapedString(p) : p;
    fwrite(s.data(), 1, s.size(), stdout);
    fwrite(&terminator, 1, 1, stdout);
  }
  return 0;
}

int RunToolMultiInputs(State* state, int argc, char** argv) {
  optind = 1;
  std::string delim = "\t";
  char terminator = '\n';
  static const struct option options[] = {
    {"help", no_argument, 0, 'h'},
    {"delimiter", required_argument, 0, 'd'},
    {"print0", no_argument, 0, '0'},
    {0, 0, 0, 0}
  };
  int c;
  while ((c = getopt_long(argc, argv, "hd:0", options, nullptr)) != -1) {
    switch (c) {
      case 'd': delim = optarg; break;
      case '0': terminator = '\0'; break;
      case 'h':
      default:
        printf(
"Usage '-t multi-inputs [options] [targets]\n\n"
"Print one or more sets of inputs required to build targets, sorted in dependency order.\n"
"The tool works like inputs tool but with addition of the target for each line.\n"
"The output will be a series of lines with the following elements:\n"
"<target> <delimiter> <input> <terminator>\n"
"Note that a given input may appear for several targets if it is used by more than one targets.\n"
"Options:\n"
"  -h, --help                   Print this message.\n"
"  -d  --delimiter=DELIM        Use DELIM instead of TAB for field delimiter.\n"
"  -0, --print0                 Use \\0, instead of \\n as a line terminator.\n");
        return 1;
    }
  }
  std::vector<Node*> targets;
  std::string err;
  if (!CollectTargets(state, argc - optind, argv + optind, &targets, &err)) {
    fprintf(stderr, "ninja: error: %s\n", err.c_str());
    return 1;
  }
  for (auto* t : targets) {
    InputsCollector col;
    std::set<Node*> ts{t};
    col.Collect(t);
    for (auto* n : col.inputs) {
      if (n == t) continue;
      printf("%s%s%s", t->path().c_str(), delim.c_str(), n->path().c_str());
      fwrite(&terminator, 1, 1, stdout);
    }
  }
  return 0;
}

// --- query ---
int RunToolQuery(State* state, int argc, char** argv) {
  if (argc == 0) {
    fprintf(stderr, "usage: ninja -t query [targets]\n");
    return 1;
  }
  for (int i = 0; i < argc; ++i) {
    std::string err;
    Node* node = CollectTarget(state, argv[i], &err);
    if (!node) { fprintf(stderr, "%s: %s\n", argv[i], err.c_str()); return 1; }
    printf("%s:\n", node->path().c_str());
    Edge* e = node->in_edge();
    if (e) {
      printf("  input: %s\n", e->rule_->name().c_str());
      for (size_t j = 0; j < e->inputs_.size(); ++j) {
        const char* label = "";
        if ((int)j >= (int)(e->inputs_.size() - e->implicit_deps_ - e->order_only_deps_)) {
          if ((int)j >= (int)(e->inputs_.size() - e->order_only_deps_)) label = "| ";
          else label = "| ";
        }
        printf("    %s%s\n", label, e->inputs_[j]->path().c_str());
      }
      if (!e->validations_.empty()) {
        printf("  validations:\n");
        for (auto* v : e->validations_) printf("    %s\n", v->path().c_str());
      }
    }
    printf("  outputs:\n");
    for (auto* oe : node->out_edges()) {
      for (auto* o : oe->outputs_) {
        printf("    %s\n", o->path().c_str());
      }
    }
  }
  return 0;
}

// --- graph ---

int RunToolGraph(State* state, int argc, char** argv) {
  std::vector<Node*> targets;
  std::string err;
  if (!CollectTargets(state, argc, argv, &targets, &err)) {
    fprintf(stderr, "ninja: error: %s\n", err.c_str());
    return 1;
  }
  printf("digraph ninja {\n");
  printf("rankdir=\"LR\"\n");
  printf("node [fontsize=10, shape=box, height=0.25]\n");
  printf("edge [fontsize=10]\n");
  std::set<Node*> vis_nodes;
  std::set<Edge*> vis_edges;
  auto node_id = [](Node* n) {
    char buf[32];
    snprintf(buf, sizeof(buf), "\"%p\"", (void*)n);
    return std::string(buf);
  };
  auto edge_id = [](Edge* e) {
    char buf[32];
    snprintf(buf, sizeof(buf), "\"%p\"", (void*)e);
    return std::string(buf);
  };

  std::function<void(Node*)> visit = [&](Node* n) {
    if (!vis_nodes.insert(n).second) return;
    Edge* e = n->in_edge();
    if (!e) {
      printf("%s [label=\"%s\"]\n", node_id(n).c_str(), n->path().c_str());
      return;
    }
    if (vis_edges.count(e)) {
      printf("%s [label=\"%s\"]\n", node_id(n).c_str(), n->path().c_str());
      return;
    }
    vis_edges.insert(e);
    if (e->inputs_.size() == 1 && e->outputs_.size() == 1) {
      // Simple edge.
      printf("%s [label=\"%s\"]\n", node_id(n).c_str(), n->path().c_str());
      printf("%s -> %s [label=\" %s\"]\n", node_id(e->inputs_[0]).c_str(),
             node_id(n).c_str(), e->rule_->name().c_str());
      visit(e->inputs_[0]);
    } else {
      // Print output node first, then edge (ellipse), then inputs.
      printf("%s [label=\"%s\"]\n", node_id(n).c_str(), n->path().c_str());
      printf("%s [label=\"%s\", shape=ellipse]\n", edge_id(e).c_str(), e->rule_->name().c_str());
      printf("%s -> %s\n", edge_id(e).c_str(), node_id(n).c_str());
      for (auto* o : e->outputs_) {
        if (o != n) printf("%s -> %s\n", edge_id(e).c_str(), node_id(o).c_str());
      }
      for (auto* in : e->inputs_) {
        printf("%s -> %s [arrowhead=none]\n", node_id(in).c_str(), edge_id(e).c_str());
      }
      for (auto* in : e->inputs_) visit(in);
    }
  };
  for (auto* t : targets) visit(t);
  printf("}\n");
  return 0;
}

// --- compdb ---
static std::string EscapeJson(const std::string& s) {
  std::string r;
  for (char c : s) {
    switch (c) {
      case '"': r += "\\\""; break;
      case '\\': r += "\\\\"; break;
      case '\b': r += "\\b"; break;
      case '\f': r += "\\f"; break;
      case '\n': r += "\\n"; break;
      case '\r': r += "\\r"; break;
      case '\t': r += "\\t"; break;
      default:
        if ((unsigned char)c < 0x20) {
          char buf[8]; snprintf(buf, sizeof(buf), "\\u%04x", c);
          r += buf;
        } else r += c;
    }
  }
  return r;
}

static std::string ExpandRspFileInCommand(const std::string& cmd, const std::string& rsp, const std::string& rsp_content) {
  if (rsp.empty()) return cmd;
  std::string needle = "@" + rsp;
  size_t pos = cmd.find(needle);
  if (pos == std::string::npos) return cmd;
  return cmd.substr(0, pos) + rsp_content + cmd.substr(pos + needle.size());
}

static void PrintCompdbEntry(const std::string& dir, Edge* e, bool expand_rsp, bool* first) {
  std::string cmd = e->EvaluateCommand();
  if (expand_rsp) {
    std::string rsp = e->GetUnescapedRspfile();
    std::string rsp_content = e->GetBinding("rspfile_content");
    cmd = ExpandRspFileInCommand(cmd, rsp, rsp_content);
  }
  for (auto* in : e->inputs_) {
    if ((size_t)(in - *e->inputs_.data()) >= e->inputs_.size() - e->implicit_deps_ - e->order_only_deps_) {
      break;
    }
    if (!*first) printf(",\n"); else *first = false;
    int explicit_n = e->inputs_.size() - e->implicit_deps_ - e->order_only_deps_;
    (void)explicit_n;
    printf("  {\n");
    printf("    \"directory\": \"%s\",\n", EscapeJson(dir).c_str());
    printf("    \"command\": \"%s\",\n", EscapeJson(cmd).c_str());
    printf("    \"file\": \"%s\",\n", EscapeJson(in->path()).c_str());
    printf("    \"output\": \"%s\"\n", e->outputs_.empty() ? "" : EscapeJson(e->outputs_[0]->path()).c_str());
    printf("  }");
  }
}

static void PrintCompdbForEdges(const std::string& dir, const std::vector<Edge*>& edges, bool expand_rsp) {
  printf("[\n");
  bool first = true;
  for (auto* e : edges) {
    if (e->rule_->name() == "phony") continue;
    int explicit_n = e->inputs_.size() - e->implicit_deps_ - e->order_only_deps_;
    std::string cmd = e->EvaluateCommand();
    if (expand_rsp) {
      std::string rsp = e->GetUnescapedRspfile();
      std::string rsp_content = e->GetBinding("rspfile_content");
      cmd = ExpandRspFileInCommand(cmd, rsp, rsp_content);
    }
    for (int i = 0; i < explicit_n; ++i) {
      if (!first) printf(",\n");
      first = false;
      printf("  {\n");
      printf("    \"directory\": \"%s\",\n", EscapeJson(dir).c_str());
      printf("    \"command\": \"%s\",\n", EscapeJson(cmd).c_str());
      printf("    \"file\": \"%s\",\n", EscapeJson(e->inputs_[i]->path()).c_str());
      printf("    \"output\": \"%s\"\n", e->outputs_.empty() ? "" : EscapeJson(e->outputs_[0]->path()).c_str());
      printf("  }");
    }
  }
  if (!first) printf("\n");
  printf("]\n");
}

int RunToolCompdb(State* state, int argc, char** argv) {
  optind = 1;
  bool expand = false;
  int c;
  while ((c = getopt(argc, argv, "hx")) != -1) {
    switch (c) {
      case 'x': expand = true; break;
      case 'h':
      default:
        printf("usage: ninja -t compdb [options] [rules]\n\noptions:\n  -x     expand @rspfile style response file invocations\n");
        return c == 'h' ? 0 : 1;
    }
  }
  char cwd[4096];
  if (!getcwd(cwd, sizeof(cwd))) strcpy(cwd, "");
  std::string dir = cwd;
  std::set<std::string> filter;
  for (int i = optind; i < argc; ++i) filter.insert(argv[i]);
  std::vector<Edge*> edges;
  for (auto* e : state->edges_) {
    if (filter.empty() || filter.count(e->rule_->name()))
      edges.push_back(e);
  }
  PrintCompdbForEdges(dir, edges, expand);
  return 0;
}

int RunToolCompdbTargets(State* state, int argc, char** argv) {
  optind = 1;
  bool expand = false;
  int c;
  while ((c = getopt(argc, argv, "hx")) != -1) {
    switch (c) {
      case 'x': expand = true; break;
      case 'h':
        printf("usage: ninja -t compdb [-hx] target [targets]\n\noptions:\n  -h     display this help message\n  -x     expand @rspfile style response file invocations\n");
        return 0;
      default:
        return 1;
    }
  }
  if (argc - optind < 1) {
    fprintf(stderr, "ninja: error: compdb-targets expects the name of at least one target\n");
    return 1;
  }
  std::vector<Node*> targets;
  std::string err;
  if (!CollectTargets(state, argc - optind, argv + optind, &targets, &err)) {
    fprintf(stderr, "ninja: error: %s\n", err.c_str()); return 1;
  }
  char cwd[4096];
  if (!getcwd(cwd, sizeof(cwd))) strcpy(cwd, "");
  std::set<Edge*> seen;
  std::vector<Edge*> edges;
  std::function<void(Node*)> visit = [&](Node* n) {
    Edge* e = n->in_edge();
    if (!e || !seen.insert(e).second) return;
    for (auto* in : e->inputs_) visit(in);
    edges.push_back(e);
  };
  for (auto* t : targets) visit(t);
  PrintCompdbForEdges(cwd, edges, expand);
  return 0;
}

