bool Lexer::PeekIndent() {
  const char* p = input_ + ofs_;
  // Skip any leading blank lines.
  while (p < end_) {
    // Check if we're at start of line (last char was newline or start of input).
    bool at_line_start = (p == input_) || (p[-1] == '\\n');
    if (!at_line_start) {
      // Skip any horizontal whitespace first.
      while (p < end_ && (*p == ' ' || *p == '\\t')) ++p;
      if (p < end_ && (*p == '\\n' || *p == '\\r')) { ++p; continue; }
