#include "clean.h"
#include "state.h"
#include "disk.h"
#include <cstdio>
#include <set>
#include <unistd.h>
#include <sys/stat.h>

int CleanAll(State* state, bool generator) {
  int count = 0;
  for (auto* edge : state->edges_) {
    if (edge->rule_->name() == "phony") continue;
    // Skip generator rules unless -g.
    if (!generator && edge->GetBindingBool("generator")) continue;
    for (auto* out : edge->outputs_) {
      struct stat st;
      if (stat(out->path().c_str(), &st) == 0) {
        if (unlink(out->path().c_str()) == 0) {
          ++count;
          printf("Remove %s\n", out->path().c_str());
        }
      }
    }
    // Remove rspfile if present.
    std::string rsp = edge->GetUnescapedRspfile();
    if (!rsp.empty()) {
      struct stat st;
      if (stat(rsp.c_str(), &st) == 0) {
        if (unlink(rsp.c_str()) == 0) ++count;
      }
    }
  }
  printf("Cleaning... %d files.\n", count);
  return 0;
}

int CleanDead(State* state) {
  // We don't have a build log, so there are no known dead files.
  printf("Cleaning... 0 files.\n");
  return 0;
}
